package agents

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"
)

type openCodeAgent struct {
	model   string
	timeout time.Duration
}

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "opencode" {
		return
	}
	if _, err := exec.LookPath("opencode"); err != nil {
		return
	}
	model := os.Getenv("E2E_OPENCODE_MODEL")
	if model == "" {
		model = "anthropic/claude-haiku-4-5"
	}
	Register(&openCodeAgent{model: model, timeout: 2 * time.Minute})
}

func (a *openCodeAgent) Name() string               { return "opencode" }
func (a *openCodeAgent) Binary() string             { return "opencode" }
func (a *openCodeAgent) EntireAgent() string        { return "opencode" }
func (a *openCodeAgent) PromptPattern() string      { return `(Ask anything|▣)` }
func (a *openCodeAgent) TimeoutMultiplier() float64 { return 2.0 }

func (a *openCodeAgent) IsTransientError(out Output, _ error) bool {
	transientPatterns := []string{
		"overloaded",
		"rate limit",
		"529",
		"503",
		"ECONNRESET",
		"ETIMEDOUT",
		"Token refresh failed",
		"database is locked",
	}
	for _, p := range transientPatterns {
		if strings.Contains(out.Stderr, p) {
			return true
		}
	}
	return false
}

func (a *openCodeAgent) Bootstrap() error {
	// opencode has first-run DB migration + node_modules resolution that
	// races with parallel test execution (upstream issue #6935).
	// Run a trivial prompt to force full initialization before tests.
	for i := range 3 {
		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		cmd := exec.CommandContext(ctx, a.Binary(), "run", "--model", a.model, "say hi")
		cmd.Env = os.Environ()
		out, err := cmd.CombinedOutput()
		cancel()
		if err == nil {
			return nil
		}
		if i < 2 {
			fmt.Fprintf(os.Stderr, "opencode warmup attempt %d failed: %s\n%s\n", i+1, err, out)
			time.Sleep(5 * time.Second)
		}
	}
	// Non-fatal: warmup failure shouldn't block tests entirely.
	fmt.Fprintln(os.Stderr, "opencode warmup failed after 3 attempts, proceeding anyway")
	return nil
}

func (a *openCodeAgent) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	cfg := &runConfig{}
	for _, o := range opts {
		o(cfg)
	}

	model := a.model
	if cfg.Model != "" {
		model = cfg.Model
	}

	args := []string{"run"}
	if model != "" {
		args = append(args, "--model", model)
	}
	args = append(args, prompt)

	timeout := a.timeout
	if envTimeout := os.Getenv("E2E_TIMEOUT"); envTimeout != "" {
		if parsed, err := time.ParseDuration(envTimeout); err == nil {
			timeout = parsed
		}
	}

	ctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	cmd := exec.CommandContext(ctx, a.Binary(), args...)
	cmd.Dir = dir
	cmd.Env = filterEnv(os.Environ(), "ENTIRE_TEST_TTY")

	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	out := Output{
		Command: a.Binary() + " " + strings.Join(args, " "),
		Stdout:  stdout.String(),
		Stderr:  stderr.String(),
	}

	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			out.ExitCode = exitErr.ExitCode()
		} else {
			out.ExitCode = -1
		}
		return out, err
	}

	return out, nil
}

func (a *openCodeAgent) StartSession(ctx context.Context, dir string) (Session, error) {
	// opencode's TUI occasionally fails to render on CI (empty pane).
	// Retry once if the first attempt produces no output at all.
	var s *TmuxSession
	var lastErr error
	for attempt := range 2 {
		name := fmt.Sprintf("opencode-test-%d", time.Now().UnixNano())
		var err error
		s, err = NewTmuxSession(name, dir, []string{"ENTIRE_TEST_TTY"}, a.Binary(), "--model", a.model)
		if err != nil {
			return nil, err
		}

		// Wait for TUI to be ready (input area with placeholder text).
		if _, err := s.WaitFor(`Ask anything`, 15*time.Second); err != nil {
			content := s.Capture()
			_ = s.Close()
			if strings.TrimSpace(content) == "" && attempt == 0 {
				lastErr = err
				continue
			}
			return nil, fmt.Errorf("waiting for startup: %w", err)
		}
		s.stableAtSend = ""
		return s, nil
	}
	return nil, fmt.Errorf("opencode TUI failed to start after retry: %w", lastErr)
}

		assert.NotEqual(t, cpID1, cpID2, "checkpoint IDs should be distinct")
		testutil.AssertCheckpointExists(t, s.Dir, cpID1)
		testutil.AssertCheckpointExists(t, s.Dir, cpID2)
		testutil.AssertNoShadowBranches(t, s.Dir)
	})
}

// TestInteractiveContentOverlapRevertNewFile: agent creates a file, user replaces its
// content entirely with different text and commits while the session is still
// idle (not ended). The content-aware overlap detection should prevent a
// checkpoint trailer (content mismatch on new file). The shadow branch
// correctly persists because the session is still active and no condensation
// occurred.
func TestInteractiveContentOverlapRevertNewFile(t *testing.T) {
	testutil.ForEachAgent(t, 2*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		prompt := s.Agent.PromptPattern()

		session := s.StartSession(t, ctx)
		if session == nil {
			t.Skipf("agent %s does not support interactive mode", s.Agent.Name())
		}

		s.WaitFor(t, session, prompt, 30*time.Second)

		s.Send(t, session, "create a markdown file at docs/red.md with a paragraph about the colour red. Don't commit, I want to make more changes.")
		s.WaitFor(t, session, prompt, 60*time.Second)
		testutil.WaitForFileExists(t, s.Dir, "docs/red.md", 30*time.Second)

		// Wait for session to transition from ACTIVE to IDLE. The prompt
		// pattern may appear before the turn-end hook completes (race between
		// TUI rendering and hook execution, especially with OpenCode).
		testutil.WaitForSessionIdle(t, s.Dir, 15*time.Second)

		// Session is now idle (turn ended, waiting for next prompt).
		// User replaces the content entirely.
		if err := os.WriteFile(filepath.Join(s.Dir, "docs", "red.md"), []byte("# Completely different content\n\nNothing about red here.\n"), 0o644); err != nil {
			t.Fatalf("overwrite file: %v", err)
		}

		s.Git(t, "add", "docs/red.md")
		s.Git(t, "commit", "-m", "Replace red.md content")

		// Give post-commit hook time to fire.
		time.Sleep(5 * time.Second)

		testutil.AssertNoCheckpointTrailer(t, s.Dir, "HEAD")
		testutil.AssertCheckpointNotAdvanced(t, s)
		// Shadow branch correctly persists: session is idle and no
		// condensation occurred (content mismatch on new file).
		testutil.AssertHasShadowBranches(t, s.Dir)
	})
}

// TestModifiedFileAlwaysGetsCheckpoint: agent modifies an existing tracked
// file, user writes completely different content and commits. A checkpoint
// should STILL be created because content-aware overlap detection only
// applies to new files, not modifications to existing tracked files.
func TestModifiedFileAlwaysGetsCheckpoint(t *testing.T) {
	testutil.ForEachAgent(t, 2*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {

		// Turn 1: Agent creates a file (tracked as touched). No commit.
		_, err := s.RunPrompt(t, ctx,
			"create a markdown file at docs/turn1.md with a paragraph about apples. Do not commit the file. Do not ask for confirmation, just make the change.")
		if err != nil {
			t.Fatalf("agent prompt 1 (turn 1) failed: %v", err)
		}
		testutil.AssertFileExists(t, s.Dir, "docs/turn1.md")

		// Turn 2: Agent creates DIFFERENT files and commits them mid-turn.
		// The committed files (turn2a.md, turn2b.md) do NOT overlap with
		// Turn 1's tracked files (turn1.md).
		_, err = s.RunPrompt(t, ctx,
			"create two markdown files: docs/turn2a.md about bananas and docs/turn2b.md about cherries. Then git add and git commit both files with a short message. Do not commit any other files. Do not ask for confirmation, just make the changes. Do not include any trailers or metadata in the commit message. Do not use worktrees.")
		if err != nil {
			t.Fatalf("agent prompt 2 (turn 2) failed: %v", err)
		}
		testutil.AssertFileExists(t, s.Dir, "docs/turn2a.md")
		testutil.AssertFileExists(t, s.Dir, "docs/turn2b.md")

		// The agent committed mid-turn, so there should be at least 1 new commit.
		testutil.AssertNewCommits(t, s, 1)

		// CRITICAL: The mid-turn commit should have triggered condensation
		// to entire/checkpoints/v1, even though committed files differ from
		// Turn 1's tracked files. This is the regression assertion.
		testutil.WaitForCheckpoint(t, s, 15*time.Second)
		testutil.AssertCheckpointAdvanced(t, s)

		cpID := testutil.AssertHasCheckpointTrailer(t, s.Dir, "HEAD")
		testutil.AssertCheckpointExists(t, s.Dir, cpID)
		testutil.AssertNoShadowBranches(t, s.Dir)
	})
}

